/* A real two-axis thumbstick and a per-orientation, local control-layout notebook. */
(() => {
 'use strict';
 const KEY='daroca-arena-layout-v1',ACTIONS=['attack','special','ultimate','jump','dash','emote'];
 const NAMES={joystick:'Joystick',attack:'Golpe físico',special:'Ataque à distância',ultimate:'Combo',jump:'Pulo',dash:'Dash',emote:'Resenha'};
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const defaults={landscape:{joystick:[.14,.84,104],attack:[.89,.86,58],special:[.92,.64,50],ultimate:[.83,.64,48],jump:[.80,.86,56],dash:[.71,.88,44],emote:[.73,.64,42]},portrait:{joystick:[.21,.87,108],attack:[.84,.89,60],special:[.88,.75,50],ultimate:[.71,.75,48],jump:[.66,.89,56],dash:[.49,.91,44],emote:[.55,.76,42]}};
 function read(){try{const data=JSON.parse(localStorage.getItem(KEY));if(data?.schema===1&&data.layouts&&typeof data.layouts==='object')return data.layouts;}catch{}return {};}
 function mount({screen,wrap,onMove=()=>{},onPress=()=>{},onRelease=()=>{},onEditing=()=>{},getState=()=>({})}){
  const layer=screen.querySelector('.arena-mobile-controls');if(!layer)return null;
  let layouts=read(),editing=false,selected='joystick',pointer=null,joyPointer=null,joy={x:0,y:0},preview=null,clearing=false,orientation='landscape',saved=true;
  const targets=new Map(),held=new Map();
  const joystick=document.createElement('div');joystick.id='arenaJoystick';joystick.className='arena-joystick arena-layout-target';joystick.dataset.layoutId='joystick';joystick.setAttribute('role','slider');joystick.setAttribute('aria-label','Joystick: andar e direcionar golpes');joystick.setAttribute('aria-valuemin','-100');joystick.setAttribute('aria-valuemax','100');joystick.setAttribute('aria-valuenow','0');
  joystick.innerHTML='<span class="arena-joystick-rim" aria-hidden="true"></span><span class="arena-joystick-knob" aria-hidden="true"><i></i></span><small>MOVER · MIRAR</small>';
  targets.set('joystick',joystick);const buttons=ACTIONS.map(action=>{const b=screen.querySelector('[data-arena-input="'+action+'"]');if(b){b.classList.add('arena-layout-target');b.dataset.layoutId=action;targets.set(action,b);}return b;}).filter(Boolean);
  layer.replaceChildren(joystick,...buttons);layer.classList.add('arena-custom-controls');
  const panel=document.createElement('section');panel.id='arenaLayoutEditor';panel.className='arena-layout-editor';panel.hidden=true;panel.setAttribute('aria-label','Editar os controles da arena');
  panel.innerHTML='<div class="alc-heading"><span>O CADERNO DOS CONTROLES</span><button type="button" data-alc-close aria-label="Concluir edição">×</button></div><h3>DO SEU JEITO, DA ROÇA.</h3><p class="alc-note">Arraste os controles. Toque em um para ajustar o tamanho.</p><div class="alc-selected"><b id="arenaLayoutSelection">Joystick</b><output id="arenaLayoutSize">104 px</output></div><input id="arenaLayoutScale" type="range" min="40" max="180" step="1" aria-label="Tamanho do controle selecionado"><div class="alc-footer"><button type="button" data-alc-keys>TECLAS DO PC</button><button type="button" data-alc-reset>RESTAURAR</button><button type="button" data-alc-done>PRONTO ✓</button></div><small id="arenaLayoutSaved" role="status"></small>';
  wrap.append(panel);
  const entry=document.createElement('button');entry.type='button';entry.id='arenaControlsBtn';entry.className='arena-small-button arena-controls-entry';entry.textContent='CONTROLES';entry.title='Teclas, joystick e posição dos botões';entry.addEventListener('click',()=>openEditor());screen.querySelector('.arena-header-actions')?.prepend(entry);
  const battleEntry=entry.cloneNode(true);battleEntry.id='arenaBattleControlsBtn';battleEntry.textContent='AJUSTAR';battleEntry.setAttribute('aria-label','Ajustar joystick, botões e teclas');battleEntry.addEventListener('click',()=>openEditor());screen.querySelector('.arena-match-top')?.insertBefore(battleEntry,screen.querySelector('#arenaBattleLeave'));
  const query=s=>panel.querySelector(s);
  function bounds(){const r=wrap.getBoundingClientRect();return {left:r.left,top:r.top,w:Math.max(1,r.width),h:Math.max(1,r.height)};}
  function setting(id){const base=defaults[orientation][id],record=layouts[orientation]?.[id];return {x:Number.isFinite(record?.x)?clamp(record.x,0,1):base[0],y:Number.isFinite(record?.y)?clamp(record.y,0,1):base[1],size:Number.isFinite(record?.size)?clamp(record.size,id==='joystick'?80:40,id==='joystick'?180:110):base[2]};}
  function persist(){try{localStorage.setItem(KEY,JSON.stringify({schema:1,layouts}));saved=true;}catch{saved=false;}query('#arenaLayoutSaved').textContent=saved?'SALVO NESTE APARELHO · '+(orientation==='landscape'?'TELA DEITADA':'TELA EM PÉ'):'Armazenamento indisponível: vale até fechar o jogo.';}
  function selectedUI(){const s=setting(selected);query('#arenaLayoutSelection').textContent=NAMES[selected];const range=query('#arenaLayoutScale');range.min=selected==='joystick'?'80':'40';range.max=selected==='joystick'?'180':'110';range.value=s.size;query('#arenaLayoutSize').textContent=Math.round(s.size)+' px';for(const[id,target]of targets)target.classList.toggle('layout-selected',editing&&id===selected);}
  function apply(){const r=bounds();if(r.w<20||r.h<20)return;orientation=r.w>=r.h?'landscape':'portrait';const style=getComputedStyle(screen),safe={};for(const side of ['top','right','bottom','left'])safe[side]=Math.max(8,(parseFloat(style.getPropertyValue('--arena-safe-'+side))||0)+8);for(const[id,target]of targets){const s=setting(id),size=Math.min(s.size,r.w-safe.left-safe.right,r.h-safe.top-safe.bottom),x=clamp(s.x*r.w,size/2+safe.left,r.w-size/2-safe.right),y=clamp(s.y*r.h,size/2+safe.top,r.h-size/2-safe.bottom);target.style.width=size+'px';target.style.height=size+'px';target.style.left=x+'px';target.style.top=y+'px';target.style.setProperty('--control-size',size+'px');}selectedUI();if(editing)persist();if(preview)paintPreview();}
  function put(id,values){layouts[orientation]||={};layouts[orientation][id]={...setting(id),...values};apply();persist();}
  function choose(id){selected=id;selectedUI();}
  function setJoy(x,y){if(window.ControlSettings?.transformJoystick){const result=ControlSettings.transformJoystick(x,y);x=result.x;y=result.y;}else{let length=Math.hypot(x,y);if(length<.15)x=y=0;else{const magnitude=Math.min(1,(length-.15)/.85);x=x/length*magnitude;y=y/length*magnitude;}}joy={x,y};joystick.style.setProperty('--joy-x',x);joystick.style.setProperty('--joy-y',y);joystick.setAttribute('aria-valuenow',String(Math.round(x*100)));joystick.setAttribute('aria-valuetext',Math.round(x*100)+' horizontal, '+Math.round(y*100)+' vertical');onMove(x,y);}
  function clear(){if(clearing)return;clearing=true;for(const[id,action]of held)onRelease(action,id);held.clear();joyPointer=null;setJoy(0,0);for(const target of targets.values())target.classList.remove('pressed');clearing=false;}
  function beginDrag(event,id,target){event.preventDefault();event.stopImmediatePropagation();choose(id);const r=target.getBoundingClientRect();pointer={id:event.pointerId,target,idName:id,offsetX:event.clientX-(r.left+r.width/2),offsetY:event.clientY-(r.top+r.height/2)};try{target.setPointerCapture(event.pointerId);}catch{}}
  for(const[id,target]of targets){
   target.addEventListener('pointerdown',event=>{if(editing){beginDrag(event,id,target);return;}if(!getState().playing||getState().eliminated||target.disabled)return;event.preventDefault();try{target.setPointerCapture(event.pointerId);}catch{}if(id==='joystick'){if(joyPointer!==null)return;joyPointer=event.pointerId;updateStick(event);}else{held.set(event.pointerId,id);target.classList.add('pressed');onPress(id,event.pointerId);}},true);
   target.addEventListener('pointermove',event=>{if(editing&&pointer?.id===event.pointerId){event.preventDefault();const r=bounds(),size=target.getBoundingClientRect().width,x=clamp(event.clientX-r.left-pointer.offsetX,size/2+5,r.w-size/2-5),y=clamp(event.clientY-r.top-pointer.offsetY,size/2+5,r.h-size/2-5);put(id,{x:x/r.w,y:y/r.h});return;}if(id==='joystick'&&joyPointer===event.pointerId){event.preventDefault();updateStick(event);}});
   const release=event=>{if(pointer?.id===event.pointerId){pointer=null;persist();}if(joyPointer===event.pointerId){joyPointer=null;setJoy(0,0);}const action=held.get(event.pointerId);if(action){held.delete(event.pointerId);onRelease(action,event.pointerId);}target.classList.remove('pressed');};target.addEventListener('pointerup',release);target.addEventListener('pointercancel',release);target.addEventListener('lostpointercapture',release);
   target.addEventListener('click',event=>{if(editing){event.preventDefault();event.stopImmediatePropagation();choose(id);}},true);
  }
  function updateStick(event){const r=joystick.getBoundingClientRect(),travel=r.width*.32;setJoy((event.clientX-r.left-r.width/2)/travel,(event.clientY-r.top-r.height/2)/travel);}
  function paintPreview(){const canvas=screen.querySelector('#arenaCanvas');if(!canvas)return;const r=canvas.getBoundingClientRect();if(r.width<20||r.height<20)return;canvas.width=Math.round(r.width);canvas.height=Math.round(r.height);const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;window.ArenaArt?.drawBackground?.(c,{x:640,y:320,zoom:.6},0,canvas.width,canvas.height);c.fillStyle='#493921';c.font='bold 14px monospace';c.textAlign='center';c.fillText('PRÉVIA DOS CONTROLES',canvas.width/2,canvas.height/2);}
  function openEditor(){if(editing)return;clear();editing=true;screen.classList.add('arena-layout-editing');const state=getState();if(!state.hasWorld){preview={lobbyHidden:screen.querySelector('#arenaLobby').hidden,battleHidden:screen.querySelector('#arenaBattle').hidden,inBattle:screen.classList.contains('in-battle')};screen.querySelector('#arenaLobby').hidden=true;screen.querySelector('#arenaBattle').hidden=false;screen.classList.add('in-battle','arena-layout-preview');}panel.hidden=false;query('.alc-note').textContent=state.practice?'O treino está pausado. Arraste e redimensione os controles.':state.playing?'A partida online continua. Seus comandos ficam parados enquanto você ajusta.':'Arraste os controles para testar a posição. O ajuste fica salvo para esta orientação.';onEditing(true);apply();persist();query('[data-alc-done]').focus();}
  function closeEditor(){if(!editing)return;clear();editing=false;pointer=null;panel.hidden=true;screen.classList.remove('arena-layout-editing','arena-layout-preview');if(preview&&!getState().hasWorld){screen.querySelector('#arenaLobby').hidden=preview.lobbyHidden;screen.querySelector('#arenaBattle').hidden=preview.battleHidden;screen.classList.toggle('in-battle',preview.inBattle);}preview=null;for(const target of targets.values())target.classList.remove('layout-selected');onEditing(false);screen.querySelector('#arenaCanvas')?.focus({preventScroll:true});}
  query('#arenaLayoutScale').addEventListener('input',event=>put(selected,{size:Number(event.target.value)}));query('[data-alc-reset]').addEventListener('click',()=>{layouts[orientation]={};apply();persist();});for(const s of ['[data-alc-close]','[data-alc-done]'])query(s).addEventListener('click',closeEditor);query('[data-alc-keys]').addEventListener('click',()=>{clear();window.ControlSettingsUI?.open?.();});
  const observer=new ResizeObserver(apply);observer.observe(wrap);window.addEventListener('orientationchange',clear);window.addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)clear();});
  apply();return Object.freeze({clear,openEditor,closeEditor,isEditing:()=>editing,refresh:apply,getVector:()=>({...joy}),getStatus:()=>({editing,selected,orientation,saved,vector:{...joy},layout:Object.fromEntries([...targets.keys()].map(id=>[id,setting(id)]))}),destroy:()=>{closeEditor();clear();observer.disconnect();panel.remove();entry.remove();battleEntry.remove();}});
 }
 window.ArenaControls=Object.freeze({mount,storageKey:KEY});
})();
